#include "main.h"
static void SystemClock_Config(void); static void MX_GPIO_Init(void);
int main(void) { HAL_Init(); SystemClock_Config(); MX_GPIO_Init(); uint32_t started=0,last_blink=0; uint8_t pressed=0,handled=0,blink=0; while (1) { uint32_t now=HAL_GetTick(); GPIO_PinState key=HAL_GPIO_ReadPin(GPIOA,GPIO_PIN_0); if(key==GPIO_PIN_RESET&&!pressed){HAL_Delay(25);if(HAL_GPIO_ReadPin(GPIOA,GPIO_PIN_0)==GPIO_PIN_RESET){pressed=1;handled=0;started=HAL_GetTick();}} if(pressed&&key==GPIO_PIN_RESET&&!handled&&HAL_GetTick()-started>=1000){blink=1;handled=1;last_blink=HAL_GetTick();} if(pressed&&key==GPIO_PIN_SET){uint32_t duration=HAL_GetTick()-started;pressed=0;if(duration<1000){if(blink)blink=0;else HAL_GPIO_TogglePin(GPIOA,GPIO_PIN_9);}} now=HAL_GetTick(); if(blink&&now-last_blink>=250){HAL_GPIO_TogglePin(GPIOA,GPIO_PIN_9);last_blink=now;} } }
static void SystemClock_Config(void) { RCC_OscInitTypeDef o={0}; RCC_ClkInitTypeDef c={0}; o.OscillatorType=RCC_OSCILLATORTYPE_HSE; o.HSEState=RCC_HSE_ON; o.HSEPredivValue=RCC_HSE_PREDIV_DIV1; o.HSIState=RCC_HSI_ON; o.PLL.PLLState=RCC_PLL_ON; o.PLL.PLLSource=RCC_PLLSOURCE_HSE; o.PLL.PLLMUL=RCC_PLL_MUL9; if(HAL_RCC_OscConfig(&o)!=HAL_OK) Error_Handler(); c.ClockType=RCC_CLOCKTYPE_HCLK|RCC_CLOCKTYPE_SYSCLK|RCC_CLOCKTYPE_PCLK1|RCC_CLOCKTYPE_PCLK2; c.SYSCLKSource=RCC_SYSCLKSOURCE_PLLCLK; c.AHBCLKDivider=RCC_SYSCLK_DIV1; c.APB1CLKDivider=RCC_HCLK_DIV2; c.APB2CLKDivider=RCC_HCLK_DIV1; if(HAL_RCC_ClockConfig(&c,FLASH_LATENCY_2)!=HAL_OK) Error_Handler(); }
static void MX_GPIO_Init(void) { GPIO_InitTypeDef g={0}; __HAL_RCC_GPIOA_CLK_ENABLE(); __HAL_RCC_GPIOD_CLK_ENABLE(); HAL_GPIO_WritePin(GPIOA,GPIO_PIN_9,GPIO_PIN_RESET); g.Pin=GPIO_PIN_0;g.Mode=GPIO_MODE_INPUT;g.Pull=GPIO_PULLUP;HAL_GPIO_Init(GPIOA,&g);g.Pin=GPIO_PIN_9;g.Mode=GPIO_MODE_OUTPUT_PP;g.Pull=GPIO_NOPULL;g.Speed=GPIO_SPEED_FREQ_LOW;HAL_GPIO_Init(GPIOA,&g); }
void Error_Handler(void){__disable_irq();while(1){}}
